"use strict";(globalThis.webpackChunkgrc||=[]).push([[85877],{15380(e){e.exports=JSON.parse('{"citeKey":"piccoli2008latticeqcd","slug":"piccoli-2008-lattice-qcd-08d3","title":"Lattice QCD Workflows: A Case Study","authors":["L. Piccoli","J. B. Kowalkowski","J. N. Simone","X.-H. Sun","H. Jin","D. J. Holmgren","N. Seenu","A. G. Singh","S. Byna","D. J. Holmgren"],"venue":"3rd International Workshop on Scientific Workflows and Business Workflow Standards in e-Science (SWBES)","type":"Workshop","entryType":"inproceedings","date":"December, 2008","year":2008,"era":"iit","month":12,"doi":"10.1109/escience.2008.168","abstract":"This paper discusses the application of existing workflow management systems to a real world science application (LQCD). Typical workflows and execution environment used in production are described. Requirements for the LQCD production system are discussed. The workflow management systems Askalon and Swift were tested by implementing the LQCD workflows and evaluated against the requirements. We report our findings and future work.","hasAbstract":true,"lede":"This paper discusses the application of existing workflow management systems to a real world science application (LQCD).","links":{"pdf":"https://grc.iit.edu/papers/2008/piccoli-2008-lattice-qcd-08d3.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["workflow"],"memberAuthors":["sun-xian-he","byna-surendra"]}')}}]);